#include "shell/document_snapshot.hpp"
namespace squiflow::shell{app::Result<void,PresentationError> validate_document_snapshot(const PreparedDocumentSnapshot&s){auto bad=[](std::string d){return app::Result<void,PresentationError>::failure({PresentationErrorCode::InvalidSnapshot,"document.error.invalid",std::move(d)});};if(s.id.empty()||s.id.size()>128)return bad("id");if(s.title.empty()||s.party.empty()||s.date.empty())return bad("header");if(s.lines.empty()||s.lines.size()>500)return bad("lines");if(s.total.empty()||s.total.size()>64||s.notes.size()>4096)return bad("totals");for(auto&l:s.lines)if(l.description.empty()||l.description.size()>1024||l.amount.empty())return bad("line");return app::Result<void,PresentationError>::success();}std::string document_template_name(DocumentKind k){switch(k){case DocumentKind::Quotation:return"quotation.html";case DocumentKind::Invoice:return"invoice.html";case DocumentKind::Statement:return"statement.html";}return"invoice.html";}}
